"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { FileViewer } from "@/components/ui/file-viewer";
import {
  PdfViewerPages,
  PdfViewerProvider,
  type PdfDocumentSource,
  type PdfViewerHandle,
} from "@/components/ui/pdf-viewer";
import {
  SegmentedDocumentProvider,
  useSegmentedDocumentViewport,
} from "@/components/ui/segmented-document-provider";
import { useSegmentedItemLink } from "@/components/ui/segmented-item-link";
import {
  ViewerBody,
  ViewerHeader,
  ViewerRoot,
  ViewerSidebar,
  ViewerSidebarTrigger,
  ViewerSurface,
} from "@/components/ui/viewer";

import {
  azureToLayoutDocument,
  type AzureDocument,
} from "./layout-blocks-azure";
import {
  documentAiPageImages,
  documentAiToLayoutDocument,
  type DocumentAiDocument,
} from "./layout-blocks-document-ai";
import { createLayoutBlocksViewerModel } from "./layout-blocks-model";
import { LayoutBlocksPanel } from "./layout-blocks-panel";
import { layoutDocumentToPdfBlob } from "./layout-blocks-pdf";
import { createOcrSegmentedDocumentModel } from "./layout-blocks-segmented-document-model";
import {
  textractToLayoutDocument,
  type TextractDocument,
} from "./layout-blocks-textract";
import type { LayoutDocument, LayoutLevel } from "./layout-blocks-types";
import { LayoutOverlayLayer } from "./layout-overlay-layer";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

const LOW_CONFIDENCE_THRESHOLD = 0.9;
const LEVEL_ORDER: LayoutLevel[] = ["block", "paragraph", "line", "word"];
const EMPTY_PAGE_IMAGES: ReadonlyMap<number, string> = new Map();

/**
 * Discriminated source for the OCR viewer. Each provider's raw output is
 * normalized to a shared {@link LayoutDocument} before rendering, so the viewer
 * itself is provider-agnostic.
 */
export type OcrSource =
  | {
      provider: "google-document-ai";
      output: DocumentAiDocument;
      pageImages?: ReadonlyMap<number, string>;
    }
  | {
      provider: "aws-textract";
      output: TextractDocument;
      pageImages?: ReadonlyMap<number, string>;
    }
  | {
      provider: "azure-document-intelligence";
      output: AzureDocument;
      pageImages?: ReadonlyMap<number, string>;
    };

export function OcrLayoutBlocks({
  className,
  heightClassName = "h-[680px]",
  source,
}: {
  className?: string;
  heightClassName?: string;
  source: OcrSource;
}) {
  const { document: layoutDocument, pageImages } = React.useMemo(
    () => normalizeOcrSource(source),
    [source],
  );
  const inspectedLevels = React.useMemo(
    () => inspectedLevelsForDocument(layoutDocument),
    [layoutDocument],
  );
  const pdfSource = useLayoutPdfSource(layoutDocument, pageImages);
  const [lowConfidenceOnly, setLowConfidenceOnly] = React.useState(false);
  const model = React.useMemo(
    () =>
      createLayoutBlocksViewerModel({
        document: layoutDocument,
        levels: inspectedLevels,
        lowConfidenceOnly,
        threshold: LOW_CONFIDENCE_THRESHOLD,
      }),
    [layoutDocument, inspectedLevels, lowConfidenceOnly],
  );
  const segmentedDocumentModel = React.useMemo(
    () =>
      createOcrSegmentedDocumentModel({
        document: layoutDocument,
        items: model.visibleItems,
      }),
    [layoutDocument, model.visibleItems],
  );

  return (
    <SegmentedDocumentProvider model={segmentedDocumentModel}>
      <OcrLayoutBlocksContent
        className={className}
        heightClassName={heightClassName}
        inspectedLevels={inspectedLevels}
        lowConfidenceOnly={lowConfidenceOnly}
        model={model}
        pdfSource={pdfSource}
        setLowConfidenceOnly={setLowConfidenceOnly}
      />
    </SegmentedDocumentProvider>
  );
}

/**
 * Back-compatible entry point for Google Document AI output. Prefer
 * {@link OcrLayoutBlocks} with an explicit {@link OcrSource} for new code.
 */
export function DocumentAiLayoutBlocks({
  className,
  heightClassName,
  output,
}: {
  className?: string;
  heightClassName?: string;
  output: DocumentAiDocument;
}) {
  const source = React.useMemo<OcrSource>(
    () => ({ provider: "google-document-ai", output }),
    [output],
  );
  return (
    <OcrLayoutBlocks
      className={className}
      heightClassName={heightClassName}
      source={source}
    />
  );
}

function OcrLayoutBlocksContent({
  className,
  heightClassName,
  inspectedLevels,
  lowConfidenceOnly,
  model,
  pdfSource,
  setLowConfidenceOnly,
}: {
  className?: string;
  heightClassName: string;
  inspectedLevels: readonly LayoutLevel[];
  lowConfidenceOnly: boolean;
  model: ReturnType<typeof createLayoutBlocksViewerModel>;
  pdfSource: ReturnType<typeof useLayoutPdfSource>;
  setLowConfidenceOnly: React.Dispatch<React.SetStateAction<boolean>>;
}) {
  const segmentedViewport = useSegmentedDocumentViewport();
  const itemLink = useSegmentedItemLink();
  const {
    activeItemId,
    clearPreview,
    navigateItem,
    previewItem,
    selectItem,
    selectedItemId,
  } = itemLink;

  const renderPageOverlay = React.useCallback(
    ({ pageNumber, rotation }: { pageNumber: number; rotation: number }) => {
      const page = model.index.pagesByNumber.get(pageNumber);
      if (!page) return null;

      return (
        <LayoutOverlayLayer
          interactive
          activeItemId={activeItemId}
          items={model.visibleItems.filter(
            (item) => item.pageNumber === pageNumber,
          )}
          page={page}
          rotation={rotation}
          selectedItemId={selectedItemId}
          visibleLevels={inspectedLevels}
          onItemClick={(item) => {
            selectItem(item.id);
            navigateItem(item.id, { behavior: "smooth", clearPreview: false });
          }}
          onItemPointerEnter={(item) => previewItem(item.id)}
          onItemPointerLeave={clearPreview}
        />
      );
    },
    [
      activeItemId,
      clearPreview,
      inspectedLevels,
      model.index.pagesByNumber,
      model.visibleItems,
      navigateItem,
      previewItem,
      selectItem,
      selectedItemId,
    ],
  );
  const setPdfViewerHandle = React.useCallback(
    (handle: PdfViewerHandle | null) => {
      segmentedViewport.documentHandlers.setDocumentHandle(handle);
    },
    [segmentedViewport.documentHandlers],
  );

  const level = inspectedLevels[0] ?? "block";

  return (
    <ViewerRoot
      data-layout-blocks=""
      className={cn("bg-background", heightClassName, className)}
      defaultOpen
      sidebarSide="right"
    >
      <ViewerHeader>
        <div className="flex items-center justify-between gap-3 p-3">
          <div className="flex min-w-0 items-center gap-2">
            <ViewerSidebarTrigger className="-ml-1" />
            <div className="flex min-w-0 items-center gap-2">
              <div className="truncate text-sm font-medium">OCR</div>
              <div className="text-muted-foreground shrink-0 text-xs">
                {levelCountLabel(level, model.visibleItems.length)}
              </div>
            </div>
          </div>
          <label className="text-muted-foreground flex shrink-0 items-center gap-2 text-xs">
            <input
              type="checkbox"
              className="size-3.5"
              checked={lowConfidenceOnly}
              onChange={(event) =>
                setLowConfidenceOnly(event.currentTarget.checked)
              }
            />
            Low confidence
          </label>
        </div>
      </ViewerHeader>
      <ViewerBody>
        <ViewerSurface>
          {pdfSource.source ? (
            <FileViewer source={pdfSource.source} className="h-full">
              <PdfViewerProvider>
                <PdfViewerPages
                  ref={setPdfViewerHandle}
                  bare
                  className="h-full"
                  onScrollProgressChange={
                    segmentedViewport.documentHandlers.onScrollProgressChange
                  }
                  onVisiblePageChange={
                    segmentedViewport.documentHandlers.onCurrentPageChange
                  }
                  renderPageOverlay={renderPageOverlay}
                />
              </PdfViewerProvider>
            </FileViewer>
          ) : (
            <div className="bg-muted/20 text-muted-foreground grid h-full place-items-center p-6 text-sm">
              {pdfSource.error ?? "Preparing OCR pages..."}
            </div>
          )}
        </ViewerSurface>
        <ViewerSidebar
          aria-label="OCR blocks"
          width="320px"
          className="bg-background flex min-h-0 shrink-0 flex-col border-l"
        >
          <LayoutBlocksPanel
            activeItemId={activeItemId}
            className="min-h-0 flex-1"
            emptyLabel={
              lowConfidenceOnly
                ? `No low-confidence OCR ${levelPlural(level)} found.`
                : `No OCR ${levelPlural(level)} found.`
            }
            items={model.evidenceItems}
            selectedItemId={selectedItemId}
            onActiveItemIdChange={previewItem}
            onNavigateItem={(item, options) => {
              navigateItem(item.id, {
                behavior: options?.behavior,
                clearPreview: options?.behavior === "auto" ? false : undefined,
              });
            }}
            onSelectedItemIdChange={(itemId) => {
              selectItem(itemId);
            }}
          />
        </ViewerSidebar>
      </ViewerBody>
    </ViewerRoot>
  );
}

function normalizeOcrSource(source: OcrSource): {
  document: LayoutDocument;
  pageImages: ReadonlyMap<number, string>;
} {
  switch (source.provider) {
    case "aws-textract":
      return {
        document: textractToLayoutDocument(source.output),
        pageImages: source.pageImages ?? EMPTY_PAGE_IMAGES,
      };
    case "azure-document-intelligence":
      return {
        document: azureToLayoutDocument(source.output),
        pageImages: source.pageImages ?? EMPTY_PAGE_IMAGES,
      };
    case "google-document-ai":
    default:
      return {
        document: documentAiToLayoutDocument(source.output),
        pageImages: source.pageImages ?? documentAiPageImages(source.output),
      };
  }
}

/** Pick the coarsest level present so the viewer always has rows to inspect. */
function inspectedLevelsForDocument(document: LayoutDocument): LayoutLevel[] {
  for (const level of LEVEL_ORDER) {
    if (document.items.some((item) => item.level === level)) return [level];
  }
  return ["block"];
}

function levelPlural(level: LayoutLevel): string {
  switch (level) {
    case "block":
      return "blocks";
    case "paragraph":
      return "paragraphs";
    case "line":
      return "lines";
    case "word":
      return "words";
  }
}

function levelCountLabel(level: LayoutLevel, count: number): string {
  const plural = levelPlural(level);
  const singular = plural.slice(0, -1);
  return `${count} ${count === 1 ? singular : plural}`;
}

function useLayoutPdfSource(
  document: LayoutDocument,
  pageImages: ReadonlyMap<number, string>,
) {
  const [state, setState] = React.useState<{
    error?: string;
    source?: PdfDocumentSource;
  }>({});

  useKeyedMountEffect(joinEffectKey([document, pageImages]), () => {
    let isCurrent = true;
    setState({});

    layoutDocumentToPdfBlob(document, new Map(pageImages))
      .then((blob) => {
        if (!isCurrent) return;
        setState({
          source: {
            kind: "blob",
            blob,
            fileName: "ocr-pages.pdf",
            identityKey: `ocr-pdf:${document.pages.length}:${pageImages.size}:${blob.size}`,
            mimeType: "application/pdf",
          },
        });
      })
      .catch((error: unknown) => {
        if (!isCurrent) return;
        setState({
          error:
            error instanceof Error
              ? error.message
              : "Failed to prepare OCR pages.",
        });
      });

    return () => {
      isCurrent = false;
    };
  });

  return state;
}

export type {
  LayoutItem,
  LayoutLevel,
  LayoutPage,
} from "./layout-blocks-types";
export type { DocumentAiDocument } from "./layout-blocks-document-ai";
export type { TextractDocument } from "./layout-blocks-textract";
export type { AzureDocument } from "./layout-blocks-azure";
export {
  documentAiPageImages,
  documentAiToLayoutDocument,
} from "./layout-blocks-document-ai";
export { textractToLayoutDocument } from "./layout-blocks-textract";
export { azureToLayoutDocument } from "./layout-blocks-azure";
export { documentAiToPdfBlob } from "./layout-blocks-document-ai-pdf";
export { layoutDocumentToPdfBlob } from "./layout-blocks-pdf";
export { createLayoutItemIndex } from "./layout-blocks-index";
export {
  createLayoutBlocksViewerModel,
  layoutItemToEvidenceItem,
} from "./layout-blocks-model";
export { LayoutBlocksPanel } from "./layout-blocks-panel";
export { LayoutOverlayLayer } from "./layout-overlay-layer";

export type LayoutLevel = "block" | "paragraph" | "line" | "word";

export type LayoutKind =
  | "title"
  | "heading"
  | "paragraph"
  | "list"
  | "table"
  | "figure"
  | "header"
  | "footer"
  | "pageNumber"
  | "other";

export type LayoutPoint = {
  x: number;
  y: number;
};

export type LayoutRect = {
  left: number;
  top: number;
  width: number;
  height: number;
};

export type LayoutQuad = [LayoutPoint, LayoutPoint, LayoutPoint, LayoutPoint];

export type LayoutTextSpan = {
  start: number;
  end: number;
};

export type LayoutItem = {
  id: string;
  pageNumber: number;
  level: LayoutLevel;
  kind: LayoutKind;
  text: string;
  confidence?: number;
  rect?: LayoutRect;
  quad?: LayoutQuad;
  parentId?: string;
  span?: LayoutTextSpan;
};

export type LayoutPage = {
  pageNumber: number;
  width: number;
  height: number;
  rotation: 0 | 90 | 180 | 270;
};

export type LayoutDocument = {
  text: string;
  pages: LayoutPage[];
  items: LayoutItem[];
};

import { normalizeLayoutQuad, quadToRect } from "./layout-blocks-geometry";
import type {
  LayoutDocument,
  LayoutItem,
  LayoutKind,
  LayoutLevel,
  LayoutPage,
  LayoutPoint,
  LayoutQuad,
  LayoutTextSpan,
} from "./layout-blocks-types";

type DocumentAiTextSegment = {
  startIndex?: string;
  endIndex?: string;
};

type DocumentAiLayout = {
  textAnchor?: {
    textSegments?: DocumentAiTextSegment[];
  };
  confidence?: number;
  boundingPoly?: {
    vertices?: Array<{ x?: number; y?: number }>;
    normalizedVertices?: Array<{ x?: number; y?: number }>;
  };
  orientation?: number;
};

type DocumentAiLayoutNode = {
  layout?: DocumentAiLayout;
};

type DocumentAiPage = {
  pageNumber?: number;
  dimension?: {
    width?: number;
    height?: number;
    unit?: string;
  };
  image?: {
    content?: string;
    mimeType?: string;
    width?: number;
    height?: number;
  };
  layout?: DocumentAiLayout;
  blocks?: DocumentAiLayoutNode[];
  paragraphs?: DocumentAiLayoutNode[];
  lines?: DocumentAiLayoutNode[];
  tokens?: DocumentAiLayoutNode[];
};

export type DocumentAiDocument = {
  text?: string;
  pages?: DocumentAiPage[];
  mimeType?: string;
  uri?: string;
};

export function documentAiToLayoutDocument(
  input: DocumentAiDocument,
): LayoutDocument {
  const text = input.text ?? "";
  const pages = (input.pages ?? []).flatMap((page, pageIndex) =>
    documentAiPageToLayoutPage(page, pageIndex),
  );
  const pagesByNumber = new Map(pages.map((page) => [page.pageNumber, page]));
  const items = (input.pages ?? []).flatMap((page, pageIndex) => {
    const pageNumber = page.pageNumber ?? pageIndex + 1;
    const layoutPage = pagesByNumber.get(pageNumber);
    if (!layoutPage) return [];

    const pageItems = [
      ...documentAiNodesToLayoutItems({
        nodes: page.blocks ?? [],
        level: "block",
        page: layoutPage,
        text,
      }),
      ...documentAiNodesToLayoutItems({
        nodes: page.paragraphs ?? [],
        level: "paragraph",
        page: layoutPage,
        text,
      }),
      ...documentAiNodesToLayoutItems({
        nodes: page.lines ?? [],
        level: "line",
        page: layoutPage,
        text,
      }),
      ...documentAiNodesToLayoutItems({
        nodes: page.tokens ?? [],
        level: "word",
        page: layoutPage,
        text,
      }),
    ];

    return assignDocumentAiParents(pageItems);
  });

  return { text, pages, items };
}

export function documentAiPageToDataUrl(page: DocumentAiPage) {
  if (!page.image?.content) return undefined;
  return `data:${page.image.mimeType ?? "image/png"};base64,${
    page.image.content
  }`;
}

/** Map of page number → embedded page-image data URL, for the PDF backdrop. */
export function documentAiPageImages(
  input: DocumentAiDocument,
): Map<number, string> {
  const images = new Map<number, string>();
  (input.pages ?? []).forEach((page, index) => {
    const dataUrl = documentAiPageToDataUrl(page);
    if (dataUrl) images.set(page.pageNumber ?? index + 1, dataUrl);
  });
  return images;
}

function documentAiPageToLayoutPage(
  page: DocumentAiPage,
  pageIndex: number,
): LayoutPage[] {
  const pageNumber = page.pageNumber ?? pageIndex + 1;
  const width = finitePositiveNumber(
    page.dimension?.width ?? page.image?.width,
  );
  const height = finitePositiveNumber(
    page.dimension?.height ?? page.image?.height,
  );

  if (!width || !height) return [];

  return [
    {
      pageNumber,
      width,
      height,
      rotation: documentAiOrientationToRotation(page.layout?.orientation),
    },
  ];
}

function documentAiNodesToLayoutItems({
  nodes,
  level,
  page,
  text,
}: {
  nodes: DocumentAiLayoutNode[];
  level: LayoutLevel;
  page: LayoutPage;
  text: string;
}): LayoutItem[] {
  return nodes.flatMap((node, index) => {
    const layout = node.layout;
    if (!layout) return [];

    const span = documentAiTextSpan(layout, text.length);
    const nodeText = span ? text.slice(span.start, span.end) : "";
    const quad = documentAiLayoutQuad(layout, page);
    const normalizedQuad = normalizeLayoutQuad(quad, page);
    if (!normalizedQuad) return [];

    return {
      id: documentAiLayoutItemId({ page, level, index, span }),
      pageNumber: page.pageNumber,
      level,
      kind: documentAiLayoutKind(level, nodeText),
      text: nodeText,
      confidence: normalizeConfidence(layout.confidence),
      quad: normalizedQuad,
      rect: quadToRect(normalizedQuad),
      span,
    };
  });
}

function documentAiTextSpan(
  layout: DocumentAiLayout,
  textLength: number,
): LayoutTextSpan | undefined {
  const segments = layout.textAnchor?.textSegments ?? [];
  if (!segments.length) return undefined;

  let start = textLength;
  let end = 0;
  for (const segment of segments) {
    const segmentStart = parseTextIndex(segment.startIndex, 0);
    const segmentEnd = parseTextIndex(segment.endIndex, segmentStart);
    start = Math.min(start, segmentStart);
    end = Math.max(end, segmentEnd);
  }

  start = clampTextIndex(start, textLength);
  end = clampTextIndex(end, textLength);

  return end >= start ? { start, end } : undefined;
}

function parseTextIndex(value: string | undefined, fallback: number) {
  if (value == null) return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function clampTextIndex(value: number, textLength: number) {
  return Math.min(textLength, Math.max(0, Math.trunc(value)));
}

function documentAiLayoutQuad(
  layout: DocumentAiLayout,
  page: LayoutPage,
): LayoutQuad | undefined {
  const vertices = layout.boundingPoly?.vertices;
  if (vertices && vertices.length >= 4) {
    return vertices.slice(0, 4).map((vertex) => ({
      x: vertex.x ?? 0,
      y: vertex.y ?? 0,
    })) as LayoutQuad;
  }

  const normalizedVertices = layout.boundingPoly?.normalizedVertices;
  if (normalizedVertices && normalizedVertices.length >= 4) {
    return normalizedVertices.slice(0, 4).map((vertex) => ({
      x: (vertex.x ?? 0) * page.width,
      y: (vertex.y ?? 0) * page.height,
    })) as LayoutQuad;
  }
}

function documentAiLayoutItemId({
  page,
  level,
  index,
  span,
}: {
  page: LayoutPage;
  level: LayoutLevel;
  index: number;
  span?: LayoutTextSpan;
}) {
  const spanKey = span ? `${span.start}-${span.end}` : "no-span";
  return `document-ai:p${page.pageNumber}:${level}:${index}:${spanKey}`;
}

function documentAiLayoutKind(level: LayoutLevel, text: string): LayoutKind {
  const trimmedText = text.trim();
  if (/^\d+$/.test(trimmedText)) return "pageNumber";
  if (level === "paragraph" || level === "block") return "paragraph";
  return "other";
}

function documentAiOrientationToRotation(
  orientation: number | undefined,
): 0 | 90 | 180 | 270 {
  switch (orientation) {
    case 2:
      return 90;
    case 3:
      return 180;
    case 4:
      return 270;
    case 1:
    default:
      return 0;
  }
}

function normalizeConfidence(confidence: number | undefined) {
  if (confidence == null || !Number.isFinite(confidence)) return undefined;
  return Math.min(1, Math.max(0, confidence));
}

function finitePositiveNumber(value: number | undefined) {
  if (value == null || !Number.isFinite(value)) return undefined;
  return Number.isFinite(value) && value > 0 ? value : undefined;
}

function assignDocumentAiParents(items: LayoutItem[]) {
  const blocks = items.filter((item) => item.level === "block");
  const paragraphs = items.filter((item) => item.level === "paragraph");
  const lines = items.filter((item) => item.level === "line");

  return items.map((item) => {
    if (item.level === "paragraph") {
      return {
        ...item,
        parentId: findSmallestContainingSpan(item, blocks)?.id,
      };
    }
    if (item.level === "line") {
      return {
        ...item,
        parentId: findSmallestContainingSpan(item, paragraphs)?.id,
      };
    }
    if (item.level === "word") {
      return { ...item, parentId: findSmallestContainingSpan(item, lines)?.id };
    }
    return item;
  });
}

function findSmallestContainingSpan(
  item: LayoutItem,
  candidates: LayoutItem[],
): LayoutItem | undefined {
  if (!item.span) return undefined;
  let parent: LayoutItem | undefined;
  let parentLength = Number.POSITIVE_INFINITY;

  for (const candidate of candidates) {
    if (!candidate.span) continue;
    if (
      candidate.span.start > item.span.start ||
      candidate.span.end < item.span.end
    ) {
      continue;
    }

    const candidateLength = candidate.span.end - candidate.span.start;
    if (candidateLength < parentLength) {
      parent = candidate;
      parentLength = candidateLength;
    }
  }

  return parent;
}

import {
  documentAiPageImages,
  documentAiToLayoutDocument,
  type DocumentAiDocument,
} from "./layout-blocks-document-ai";
import { layoutDocumentToPdfBlob } from "./layout-blocks-pdf";

export async function documentAiToPdfBlob(
  document: DocumentAiDocument,
): Promise<Blob> {
  return layoutDocumentToPdfBlob(
    documentAiToLayoutDocument(document),
    documentAiPageImages(document),
  );
}

import { normalizeLayoutQuad, quadToRect } from "./layout-blocks-geometry";
import type {
  LayoutDocument,
  LayoutItem,
  LayoutKind,
  LayoutLevel,
  LayoutPage,
  LayoutQuad,
} from "./layout-blocks-types";

type TextractPoint = {
  X?: number;
  Y?: number;
};

type TextractBoundingBox = {
  Width?: number;
  Height?: number;
  Left?: number;
  Top?: number;
};

type TextractGeometry = {
  BoundingBox?: TextractBoundingBox;
  Polygon?: TextractPoint[];
};

type TextractRelationship = {
  Type?: string;
  Ids?: string[];
};

export type TextractBlock = {
  Id?: string;
  BlockType?: string;
  Text?: string;
  Confidence?: number;
  Page?: number;
  Geometry?: TextractGeometry;
  Relationships?: TextractRelationship[];
};

export type TextractDocument = {
  DocumentMetadata?: {
    Pages?: number;
    /**
     * Retab fixture extension: Textract geometry is normalized and the service
     * response does not include source page dimensions. Generated showcase
     * fixtures can carry page dimensions here so overlays keep the source aspect.
     */
    PageSizes?: Array<{ Page?: number; Width?: number; Height?: number }>;
  };
  Blocks?: TextractBlock[];
};

export type TextractAdapterOptions = {
  /**
   * Textract geometry is normalized to the page (0–1) and the response carries
   * no pixel dimensions, so we project boxes onto a synthetic page. Defaults to
   * a US-Letter aspect ratio.
   */
  pageSize?: { width: number; height: number };
};

const DEFAULT_PAGE_SIZE = { width: 1000, height: 1294 };

const LAYOUT_BLOCK_TYPES = new Set([
  "LAYOUT_TITLE",
  "LAYOUT_HEADER",
  "LAYOUT_FOOTER",
  "LAYOUT_SECTION_HEADER",
  "LAYOUT_PAGE_NUMBER",
  "LAYOUT_LIST",
  "LAYOUT_TABLE",
  "LAYOUT_FIGURE",
  "LAYOUT_KEY_VALUE",
  "LAYOUT_TEXT",
]);

export function textractToLayoutDocument(
  input: TextractDocument,
  options: TextractAdapterOptions = {},
): LayoutDocument {
  const blocks = input.Blocks ?? [];
  const blocksById = new Map<string, TextractBlock>();
  for (const block of blocks) {
    if (block.Id) blocksById.set(block.Id, block);
  }

  const pageNumbers = collectPageNumbers(blocks);
  const metadataPageSizes = collectMetadataPageSizes(input);
  const pages: LayoutPage[] = pageNumbers.map((pageNumber) => {
    const pageSize =
      options.pageSize ??
      metadataPageSizes.get(pageNumber) ??
      DEFAULT_PAGE_SIZE;
    return {
      pageNumber,
      width: pageSize.width,
      height: pageSize.height,
      rotation: 0,
    };
  });
  const pagesByNumber = new Map(pages.map((page) => [page.pageNumber, page]));

  // Reverse-index CHILD relationships so each block can find its parent.
  const parentByChildId = new Map<string, string>();
  for (const block of blocks) {
    if (!block.Id) continue;
    for (const relationship of block.Relationships ?? []) {
      if (relationship.Type !== "CHILD") continue;
      for (const childId of relationship.Ids ?? []) {
        parentByChildId.set(childId, block.Id);
      }
    }
  }

  const items: LayoutItem[] = [];
  const textParts: string[] = [];
  let cursor = 0;

  for (const block of blocks) {
    const level = textractLevel(block.BlockType);
    if (!level || !block.Id) continue;

    const page = pagesByNumber.get(block.Page ?? 1);
    if (!page) continue;

    const quad = textractQuad(block.Geometry, page);
    const normalizedQuad = normalizeLayoutQuad(quad, page);
    if (!normalizedQuad) continue;

    const text = textractBlockText(block, blocksById);
    const span =
      text.length > 0
        ? { start: cursor, end: cursor + text.length }
        : undefined;
    if (text.length > 0) {
      textParts.push(text);
      cursor += text.length + 1;
    }

    items.push({
      id: `textract:${block.Id}`,
      pageNumber: page.pageNumber,
      level,
      kind: textractKind(block.BlockType, text),
      text,
      confidence: normalizeConfidence(block.Confidence),
      quad: normalizedQuad,
      rect: quadToRect(normalizedQuad),
      span,
      parentId: textractParentId(block.Id, parentByChildId),
    });
  }

  return { text: textParts.join("\n"), pages, items };
}

function collectPageNumbers(blocks: TextractBlock[]): number[] {
  const numbers = new Set<number>();
  for (const block of blocks) {
    numbers.add(block.Page ?? 1);
  }
  if (numbers.size === 0) numbers.add(1);
  return [...numbers].sort((a, b) => a - b);
}

function collectMetadataPageSizes(
  input: TextractDocument,
): Map<number, { width: number; height: number }> {
  const pageSizes = new Map<number, { width: number; height: number }>();

  for (const pageSize of input.DocumentMetadata?.PageSizes ?? []) {
    const pageNumber = pageSize.Page;
    const width = finitePositiveNumber(pageSize.Width);
    const height = finitePositiveNumber(pageSize.Height);
    if (pageNumber == null || !width || !height) continue;
    pageSizes.set(pageNumber, { width, height });
  }

  return pageSizes;
}

function textractLevel(blockType: string | undefined): LayoutLevel | undefined {
  if (blockType === "LINE") return "line";
  if (blockType === "WORD") return "word";
  if (blockType && LAYOUT_BLOCK_TYPES.has(blockType)) return "block";
  return undefined;
}

function textractParentId(
  blockId: string,
  parentByChildId: Map<string, string>,
): string | undefined {
  const parentId = parentByChildId.get(blockId);
  return parentId ? `textract:${parentId}` : undefined;
}

function textractBlockText(
  block: TextractBlock,
  blocksById: Map<string, TextractBlock>,
): string {
  if (typeof block.Text === "string" && block.Text.length > 0) {
    return block.Text;
  }

  // LAYOUT_* blocks carry no Text — assemble it from their child lines.
  const childTexts: string[] = [];
  for (const relationship of block.Relationships ?? []) {
    if (relationship.Type !== "CHILD") continue;
    for (const childId of relationship.Ids ?? []) {
      const child = blocksById.get(childId);
      if (child?.Text) childTexts.push(child.Text);
    }
  }
  return childTexts.join(" ");
}

function textractQuad(
  geometry: TextractGeometry | undefined,
  page: LayoutPage,
): LayoutQuad | undefined {
  const polygon = geometry?.Polygon;
  if (polygon && polygon.length >= 4) {
    return polygon.slice(0, 4).map((point) => ({
      x: (point.X ?? 0) * page.width,
      y: (point.Y ?? 0) * page.height,
    })) as LayoutQuad;
  }

  const box = geometry?.BoundingBox;
  if (box) {
    const left = (box.Left ?? 0) * page.width;
    const top = (box.Top ?? 0) * page.height;
    const width = (box.Width ?? 0) * page.width;
    const height = (box.Height ?? 0) * page.height;
    return [
      { x: left, y: top },
      { x: left + width, y: top },
      { x: left + width, y: top + height },
      { x: left, y: top + height },
    ];
  }

  return undefined;
}

function textractKind(blockType: string | undefined, text: string): LayoutKind {
  switch (blockType) {
    case "LAYOUT_TITLE":
      return "title";
    case "LAYOUT_HEADER":
      return "header";
    case "LAYOUT_SECTION_HEADER":
      return "heading";
    case "LAYOUT_FOOTER":
      return "footer";
    case "LAYOUT_PAGE_NUMBER":
      return "pageNumber";
    case "LAYOUT_LIST":
      return "list";
    case "LAYOUT_TABLE":
      return "table";
    case "LAYOUT_FIGURE":
      return "figure";
    case "LAYOUT_TEXT":
    case "LAYOUT_KEY_VALUE":
      return "paragraph";
    default:
      return /^\d+$/.test(text.trim()) ? "pageNumber" : "other";
  }
}

function normalizeConfidence(confidence: number | undefined) {
  if (confidence == null || !Number.isFinite(confidence)) return undefined;
  // Textract reports confidence on a 0–100 scale.
  return Math.min(1, Math.max(0, confidence / 100));
}

function finitePositiveNumber(value: number | undefined) {
  if (value == null || !Number.isFinite(value) || value <= 0) return undefined;
  return value;
}

import { normalizeLayoutQuad, quadToRect } from "./layout-blocks-geometry";
import type {
  LayoutDocument,
  LayoutItem,
  LayoutKind,
  LayoutLevel,
  LayoutPage,
  LayoutQuad,
  LayoutTextSpan,
} from "./layout-blocks-types";

type AzureSpan = {
  offset?: number;
  length?: number;
};

type AzureWord = {
  content?: string;
  polygon?: number[];
  confidence?: number;
  span?: AzureSpan;
};

type AzureLine = {
  content?: string;
  polygon?: number[];
  spans?: AzureSpan[];
};

type AzurePage = {
  pageNumber?: number;
  angle?: number;
  width?: number;
  height?: number;
  unit?: string;
  words?: AzureWord[];
  lines?: AzureLine[];
};

type AzureBoundingRegion = {
  pageNumber?: number;
  polygon?: number[];
};

type AzureParagraph = {
  role?: string;
  content?: string;
  boundingRegions?: AzureBoundingRegion[];
  spans?: AzureSpan[];
};

export type AzureAnalyzeResult = {
  apiVersion?: string;
  modelId?: string;
  content?: string;
  pages?: AzurePage[];
  paragraphs?: AzureParagraph[];
};

export type AzureDocument =
  | AzureAnalyzeResult
  | { analyzeResult?: AzureAnalyzeResult };

export function azureToLayoutDocument(input: AzureDocument): LayoutDocument {
  const result = resolveAnalyzeResult(input);
  const text = result.content ?? "";

  const pages: LayoutPage[] = [];
  const pageScaleByNumber = new Map<number, number>();
  (result.pages ?? []).forEach((page, index) => {
    const pageNumber = page.pageNumber ?? index + 1;
    const scale = azureUnitScale(page.unit);
    const width = finitePositiveNumber((page.width ?? 0) * scale);
    const height = finitePositiveNumber((page.height ?? 0) * scale);
    if (!width || !height) return;
    pageScaleByNumber.set(pageNumber, scale);
    pages.push({
      pageNumber,
      width,
      height,
      rotation: normalizeAngle(page.angle),
    });
  });
  const pagesByNumber = new Map(pages.map((page) => [page.pageNumber, page]));

  const blocks: LayoutItem[] = [];
  (result.paragraphs ?? []).forEach((paragraph, index) => {
    const region = paragraph.boundingRegions?.[0];
    const pageNumber = region?.pageNumber;
    const page = pageNumber != null ? pagesByNumber.get(pageNumber) : undefined;
    if (!page) return;
    const scale = pageScaleByNumber.get(page.pageNumber) ?? 1;
    const item = buildItem({
      id: `azure:p${page.pageNumber}:block:${index}`,
      level: "block",
      kind: azureRoleToKind(paragraph.role),
      text: paragraph.content ?? "",
      page,
      polygon: region?.polygon,
      scale,
      span: azureSpan(paragraph.spans),
    });
    if (item) blocks.push(item);
  });

  const lines: LayoutItem[] = [];
  const words: LayoutItem[] = [];
  (result.pages ?? []).forEach((page, pageIndex) => {
    const pageNumber = page.pageNumber ?? pageIndex + 1;
    const layoutPage = pagesByNumber.get(pageNumber);
    if (!layoutPage) return;
    const scale = pageScaleByNumber.get(pageNumber) ?? 1;

    (page.lines ?? []).forEach((line, index) => {
      const item = buildItem({
        id: `azure:p${pageNumber}:line:${index}`,
        level: "line",
        kind: azureTextKind(line.content ?? ""),
        text: line.content ?? "",
        page: layoutPage,
        polygon: line.polygon,
        scale,
        span: azureSpan(line.spans),
      });
      if (item) lines.push(item);
    });
    (page.words ?? []).forEach((word, index) => {
      const item = buildItem({
        id: `azure:p${pageNumber}:word:${index}`,
        level: "word",
        kind: azureTextKind(word.content ?? ""),
        text: word.content ?? "",
        page: layoutPage,
        polygon: word.polygon,
        scale,
        span: word.span ? azureSpan([word.span]) : undefined,
        confidence: word.confidence,
      });
      if (item) words.push(item);
    });
  });

  // Derive hierarchy from text-span containment: word → line → block.
  const linkedWords = words.map((word) => ({
    ...word,
    parentId: findSmallestContainingSpan(word, lines)?.id,
  }));
  const linkedLines = lines.map((line) => ({
    ...line,
    parentId: findSmallestContainingSpan(line, blocks)?.id,
  }));

  return { text, pages, items: [...blocks, ...linkedLines, ...linkedWords] };
}

function buildItem({
  id,
  level,
  kind,
  text,
  page,
  polygon,
  scale,
  span,
  confidence,
}: {
  id: string;
  level: LayoutLevel;
  kind: LayoutKind;
  text: string;
  page: LayoutPage;
  polygon: number[] | undefined;
  scale: number;
  span?: LayoutTextSpan;
  confidence?: number;
}): LayoutItem | undefined {
  const quad = azurePolygonToQuad(polygon, scale);
  const normalizedQuad = normalizeLayoutQuad(quad, page);
  if (!normalizedQuad) return undefined;

  return {
    id,
    pageNumber: page.pageNumber,
    level,
    kind,
    text,
    confidence: normalizeConfidence(confidence),
    quad: normalizedQuad,
    rect: quadToRect(normalizedQuad),
    span,
  };
}

function resolveAnalyzeResult(input: AzureDocument): AzureAnalyzeResult {
  if (input && "analyzeResult" in input && input.analyzeResult) {
    return input.analyzeResult;
  }
  return input as AzureAnalyzeResult;
}

function azurePolygonToQuad(
  polygon: number[] | undefined,
  scale: number,
): LayoutQuad | undefined {
  if (!polygon || polygon.length < 8) return undefined;
  return [
    { x: polygon[0] * scale, y: polygon[1] * scale },
    { x: polygon[2] * scale, y: polygon[3] * scale },
    { x: polygon[4] * scale, y: polygon[5] * scale },
    { x: polygon[6] * scale, y: polygon[7] * scale },
  ];
}

function azureSpan(spans: AzureSpan[] | undefined): LayoutTextSpan | undefined {
  if (!spans || spans.length === 0) return undefined;
  let start = Number.POSITIVE_INFINITY;
  let end = 0;
  for (const span of spans) {
    const offset = span.offset ?? 0;
    const length = span.length ?? 0;
    start = Math.min(start, offset);
    end = Math.max(end, offset + length);
  }
  if (!Number.isFinite(start) || end < start) return undefined;
  return { start, end };
}

function findSmallestContainingSpan(
  item: LayoutItem,
  candidates: LayoutItem[],
): LayoutItem | undefined {
  if (!item.span) return undefined;
  let parent: LayoutItem | undefined;
  let parentLength = Number.POSITIVE_INFINITY;

  for (const candidate of candidates) {
    if (!candidate.span) continue;
    if (candidate.pageNumber !== item.pageNumber) continue;
    if (
      candidate.span.start > item.span.start ||
      candidate.span.end < item.span.end
    ) {
      continue;
    }
    const candidateLength = candidate.span.end - candidate.span.start;
    if (candidateLength < parentLength) {
      parent = candidate;
      parentLength = candidateLength;
    }
  }

  return parent;
}

function azureUnitScale(unit: string | undefined): number {
  switch (unit) {
    case "inch":
      return 96;
    case "centimeter":
      return 96 / 2.54;
    case "pixel":
    default:
      return 1;
  }
}

function normalizeAngle(angle: number | undefined): 0 | 90 | 180 | 270 {
  if (angle == null || !Number.isFinite(angle)) return 0;
  const normalized = (((Math.round(angle / 90) * 90) % 360) + 360) % 360;
  return normalized as 0 | 90 | 180 | 270;
}

function azureRoleToKind(role: string | undefined): LayoutKind {
  switch (role) {
    case "title":
      return "title";
    case "sectionHeading":
      return "heading";
    case "pageHeader":
      return "header";
    case "pageFooter":
      return "footer";
    case "pageNumber":
      return "pageNumber";
    case "footnote":
      return "other";
    default:
      return "paragraph";
  }
}

function azureTextKind(text: string): LayoutKind {
  return /^\d+$/.test(text.trim()) ? "pageNumber" : "other";
}

function normalizeConfidence(confidence: number | undefined) {
  if (confidence == null || !Number.isFinite(confidence)) return undefined;
  return Math.min(1, Math.max(0, confidence));
}

function finitePositiveNumber(value: number | undefined) {
  if (value == null || !Number.isFinite(value) || value <= 0) return undefined;
  return value;
}

import type { LayoutDocument, LayoutPage } from "./layout-blocks-types";

type PdfImagePage = {
  data: Uint8Array;
  width: number;
  height: number;
};

const PDF_TEXT_ENCODER = new TextEncoder();
const PDF_JPEG_QUALITY = 0.92;

/**
 * Render a normalized layout document into a PDF that the viewer can display.
 * Pages with a backdrop image (e.g. Google Document AI) draw that image; pages
 * without one (e.g. AWS Textract / Azure Document Intelligence, which return no
 * page bitmap) fall back to a blank white page sized to the page dimensions so
 * the OCR overlays still have a surface to anchor to.
 */
export async function layoutDocumentToPdfBlob(
  document: LayoutDocument,
  pageImages?: Map<number, string>,
): Promise<Blob> {
  if (!document.pages.length) {
    throw new Error("OCR output has no pages to render.");
  }

  const imagePages = await Promise.all(
    document.pages.map((page) =>
      layoutPageToPdfImage(page, pageImages?.get(page.pageNumber)),
    ),
  );

  return new Blob([writePdf(imagePages)], { type: "application/pdf" });
}

async function layoutPageToPdfImage(
  page: LayoutPage,
  dataUrl: string | undefined,
): Promise<PdfImagePage> {
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(page.width));
  canvas.height = Math.max(1, Math.round(page.height));

  const context = canvas.getContext("2d");
  if (!context) throw new Error("Canvas 2D context is unavailable.");

  context.fillStyle = "#fff";
  context.fillRect(0, 0, canvas.width, canvas.height);

  if (dataUrl) {
    const image = await loadImage(dataUrl);
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
  }

  const jpegDataUrl = canvas.toDataURL("image/jpeg", PDF_JPEG_QUALITY);
  return {
    data: dataUrlToBytes(jpegDataUrl),
    width: canvas.width,
    height: canvas.height,
  };
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error("Failed to load OCR page image."));
    image.src = src;
  });
}

function writePdf(pages: PdfImagePage[]) {
  const chunks: Uint8Array[] = [];
  const offsets: number[] = [0];
  let position = 0;
  let objectNumber = 1;

  function write(value: string | Uint8Array) {
    const chunk =
      typeof value === "string" ? PDF_TEXT_ENCODER.encode(value) : value;
    chunks.push(chunk);
    position += chunk.length;
  }

  function beginObject() {
    offsets[objectNumber] = position;
    write(`${objectNumber} 0 obj\n`);
    return objectNumber++;
  }

  function endObject() {
    write("endobj\n");
  }

  write("%PDF-1.4\n%\xE2\xE3\xCF\xD3\n");

  const catalogObject = beginObject();
  write("<< /Type /Catalog /Pages 2 0 R >>\n");
  endObject();

  const pagesObject = beginObject();
  const firstPageObject = 3;
  const pageObjectNumbers = pages.map(
    (_, index) => firstPageObject + index * 3,
  );
  write(
    `<< /Type /Pages /Count ${pages.length} /Kids [${pageObjectNumbers
      .map((pageObject) => `${pageObject} 0 R`)
      .join(" ")}] >>\n`,
  );
  endObject();

  for (const [index, page] of pages.entries()) {
    const pageObject = beginObject();
    const imageObject = pageObject + 1;
    const contentObject = pageObject + 2;
    write(
      `<< /Type /Page /Parent ${pagesObject} 0 R /MediaBox [0 0 ${page.width} ${page.height}] /Resources << /XObject << /Im${index + 1} ${imageObject} 0 R >> >> /Contents ${contentObject} 0 R >>\n`,
    );
    endObject();

    beginObject();
    write(
      `<< /Type /XObject /Subtype /Image /Width ${page.width} /Height ${page.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${page.data.length} >>\nstream\n`,
    );
    write(page.data);
    write("\nendstream\n");
    endObject();

    const content = `q\n${page.width} 0 0 ${page.height} 0 0 cm\n/Im${index + 1} Do\nQ\n`;
    beginObject();
    write(`<< /Length ${PDF_TEXT_ENCODER.encode(content).length} >>\nstream\n`);
    write(content);
    write("endstream\n");
    endObject();
  }

  const xrefOffset = position;
  write(`xref\n0 ${objectNumber}\n`);
  write("0000000000 65535 f \n");
  for (let index = 1; index < objectNumber; index += 1) {
    write(`${String(offsets[index]).padStart(10, "0")} 00000 n \n`);
  }
  write(
    `trailer\n<< /Size ${objectNumber} /Root ${catalogObject} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`,
  );

  const bytes = new Uint8Array(position);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  return bytes;
}

function dataUrlToBytes(dataUrl: string) {
  const base64 = dataUrl.split(",")[1];
  if (!base64) throw new Error("Invalid image data URL.");
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

import type {
  LayoutItem,
  LayoutPage,
  LayoutPoint,
  LayoutQuad,
  LayoutRect,
} from "./layout-blocks-types";

export function clampLayoutValue(value: number, min: number, max: number) {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, value));
}

export function normalizeLayoutRect(
  rect: LayoutRect | undefined,
  page: LayoutPage,
): LayoutRect | null {
  if (!rect) return null;
  if (
    !Number.isFinite(rect.left) ||
    !Number.isFinite(rect.top) ||
    !Number.isFinite(rect.width) ||
    !Number.isFinite(rect.height) ||
    rect.width <= 0 ||
    rect.height <= 0 ||
    page.width <= 0 ||
    page.height <= 0
  ) {
    return null;
  }

  const left = clampLayoutValue(rect.left, 0, page.width);
  const top = clampLayoutValue(rect.top, 0, page.height);
  const right = clampLayoutValue(rect.left + rect.width, 0, page.width);
  const bottom = clampLayoutValue(rect.top + rect.height, 0, page.height);
  const width = right - left;
  const height = bottom - top;

  return width > 0 && height > 0 ? { left, top, width, height } : null;
}

export function quadToRect(quad: LayoutQuad): LayoutRect {
  const xValues = quad.map((point) => point.x);
  const yValues = quad.map((point) => point.y);
  const left = Math.min(...xValues);
  const top = Math.min(...yValues);
  const right = Math.max(...xValues);
  const bottom = Math.max(...yValues);

  return {
    left,
    top,
    width: right - left,
    height: bottom - top,
  };
}

export function rectToQuad(rect: LayoutRect): LayoutQuad {
  return [
    { x: rect.left, y: rect.top },
    { x: rect.left + rect.width, y: rect.top },
    { x: rect.left + rect.width, y: rect.top + rect.height },
    { x: rect.left, y: rect.top + rect.height },
  ];
}

export function normalizeLayoutQuad(
  quad: LayoutQuad | undefined,
  page: LayoutPage,
): LayoutQuad | null {
  if (!quad || page.width <= 0 || page.height <= 0) return null;
  const normalizedQuad = quad.map((point) => ({
    x: clampLayoutValue(point.x, 0, page.width),
    y: clampLayoutValue(point.y, 0, page.height),
  })) as LayoutQuad;
  const rect = quadToRect(normalizedQuad);

  return rect.width > 0 && rect.height > 0 ? normalizedQuad : null;
}

export function normalizeRotation(rotation: number): 0 | 90 | 180 | 270 {
  const normalized = ((rotation % 360) + 360) % 360;
  if (normalized < 45 || normalized >= 315) return 0;
  if (normalized < 135) return 90;
  if (normalized < 225) return 180;
  return 270;
}

export function getRotatedPageSize(
  page: LayoutPage,
  rotation: number = page.rotation,
) {
  const normalizedRotation = normalizeRotation(rotation);
  return normalizedRotation === 90 || normalizedRotation === 270
    ? { width: page.height, height: page.width }
    : { width: page.width, height: page.height };
}

export function rotatePoint(
  point: LayoutPoint,
  page: LayoutPage,
  rotation: number = page.rotation,
): LayoutPoint {
  switch (normalizeRotation(rotation)) {
    case 90:
      return { x: page.height - point.y, y: point.x };
    case 180:
      return { x: page.width - point.x, y: page.height - point.y };
    case 270:
      return { x: point.y, y: page.width - point.x };
    case 0:
    default:
      return point;
  }
}

export function rotateQuad(
  quad: LayoutQuad,
  page: LayoutPage,
  rotation: number = page.rotation,
): LayoutQuad {
  return quad.map((point) => rotatePoint(point, page, rotation)) as LayoutQuad;
}

export function itemToQuad(
  item: LayoutItem,
  page: LayoutPage,
): LayoutQuad | null {
  const quad = normalizeLayoutQuad(item.quad, page);
  if (quad) return quad;
  const rect = normalizeLayoutRect(item.rect, page);
  return rect ? rectToQuad(rect) : null;
}

export function itemToRect(
  item: LayoutItem,
  page: LayoutPage,
): LayoutRect | null {
  const quad = itemToQuad(item, page);
  return quad ? quadToRect(quad) : normalizeLayoutRect(item.rect, page);
}

export function toPercentRect(
  rect: LayoutRect,
  page: LayoutPage,
  rotation: number = page.rotation,
): LayoutRect {
  const size = getRotatedPageSize(page, rotation);
  return {
    left: (rect.left / size.width) * 100,
    top: (rect.top / size.height) * 100,
    width: (rect.width / size.width) * 100,
    height: (rect.height / size.height) * 100,
  };
}

export function toSvgPoints(
  quad: LayoutQuad,
  page: LayoutPage,
  rotation: number = page.rotation,
): string {
  const rotatedQuad = rotateQuad(quad, page, rotation);
  const size = getRotatedPageSize(page, rotation);

  return rotatedQuad
    .map(
      (point) =>
        `${(point.x / size.width) * 100},${(point.y / size.height) * 100}`,
    )
    .join(" ");
}

export function getScrollTarget(item: LayoutItem, page: LayoutPage) {
  const rect = itemToRect(item, page);

  return {
    pageNumber: item.pageNumber,
    left: rect ? (rect.left / page.width) * 100 : 0,
    top: rect ? (rect.top / page.height) * 100 : 0,
    width: rect ? (rect.width / page.width) * 100 : 0,
    height: rect ? (rect.height / page.height) * 100 : 0,
  };
}

import type {
  LayoutItem,
  LayoutLevel,
  LayoutPage,
} from "./layout-blocks-types";

export type LayoutItemIndex = {
  itemsById: Map<string, LayoutItem>;
  itemsByPage: Map<number, LayoutItem[]>;
  itemsByLevel: Map<LayoutLevel, LayoutItem[]>;
  pagesByNumber: Map<number, LayoutPage>;
};

export function createLayoutItemIndex({
  items,
  pages,
}: {
  items: LayoutItem[];
  pages: LayoutPage[];
}): LayoutItemIndex {
  const itemsById = new Map<string, LayoutItem>();
  const itemsByPage = new Map<number, LayoutItem[]>();
  const itemsByLevel = new Map<LayoutLevel, LayoutItem[]>();
  const pagesByNumber = new Map<number, LayoutPage>();

  for (const page of pages) {
    pagesByNumber.set(page.pageNumber, page);
  }

  for (const item of items) {
    itemsById.set(item.id, item);
    appendMapValue(itemsByPage, item.pageNumber, item);
    appendMapValue(itemsByLevel, item.level, item);
  }

  return {
    itemsById,
    itemsByPage,
    itemsByLevel,
    pagesByNumber,
  };
}

function appendMapValue<Key, Value>(
  map: Map<Key, Value[]>,
  key: Key,
  value: Value,
) {
  const values = map.get(key);
  if (values) {
    values.push(value);
    return;
  }
  map.set(key, [value]);
}

export function getLayoutItemsForPage({
  index,
  pageNumber,
  levels,
}: {
  index: LayoutItemIndex;
  pageNumber: number;
  levels?: readonly LayoutLevel[];
}) {
  const pageItems = index.itemsByPage.get(pageNumber) ?? [];
  if (!levels?.length) return pageItems;
  const levelSet = new Set(levels);
  return pageItems.filter((item) => levelSet.has(item.level));
}

import {
  missingEvidenceAnchor,
  resolvedEvidenceAnchor,
  type EvidenceItem,
} from "./document-evidence";
import { getScrollTarget } from "./layout-blocks-geometry";
import {
  createLayoutItemIndex as createLayoutItemIndexForItems,
  type LayoutItemIndex,
} from "./layout-blocks-index";
import type {
  LayoutDocument,
  LayoutItem,
  LayoutLevel,
} from "./layout-blocks-types";

export type LayoutEvidencePayload = {
  item: LayoutItem;
  level: LayoutLevel;
  kind: string;
  text: string;
  confidence?: number;
  pageNumber: number;
};

export type LayoutEvidenceItem = EvidenceItem<LayoutEvidencePayload>;

export type LayoutBlocksFilter = {
  levels: readonly LayoutLevel[];
  lowConfidenceOnly?: boolean;
  threshold: number;
};

export type LayoutBlocksViewerModel = {
  evidenceItems: LayoutEvidenceItem[];
  index: LayoutItemIndex;
  visibleItems: LayoutItem[];
};

export function createLayoutBlocksViewerModel({
  document,
  levels,
  lowConfidenceOnly = false,
  threshold,
}: {
  document: LayoutDocument;
  levels: readonly LayoutLevel[];
  lowConfidenceOnly?: boolean;
  threshold: number;
}): LayoutBlocksViewerModel {
  const index = createLayoutItemIndex(document);
  const visibleItems = filterLayoutItems(document.items, {
    levels,
    lowConfidenceOnly,
    threshold,
  });

  return {
    ...layoutItemsToEvidenceModel(visibleItems, index),
    index,
    visibleItems,
  };
}

export function createLayoutItemIndex(
  document: LayoutDocument,
): LayoutItemIndex {
  return createLayoutItemIndexForItems({
    items: document.items,
    pages: document.pages,
  });
}

export function filterLayoutItems(
  items: readonly LayoutItem[],
  { levels, lowConfidenceOnly = false, threshold }: LayoutBlocksFilter,
): LayoutItem[] {
  const levelSet = new Set(levels);
  return items.filter((item) => {
    if (!levelSet.has(item.level)) return false;
    if (!lowConfidenceOnly) return true;
    return item.confidence != null && item.confidence < threshold;
  });
}

export function layoutItemsToEvidenceModel(
  items: readonly LayoutItem[],
  index: LayoutItemIndex,
) {
  const evidenceItems = items.map((item) =>
    layoutItemToEvidenceItem(item, index),
  );
  return {
    evidenceItems,
  };
}

export function layoutItemToEvidenceItem(
  item: LayoutItem,
  index: LayoutItemIndex,
): LayoutEvidenceItem {
  const page = index.pagesByNumber.get(item.pageNumber);
  const target = page ? getScrollTarget(item, page) : null;

  return {
    id: item.id,
    anchor: target
      ? resolvedEvidenceAnchor({
          kind: "pdf-area",
          pageNumber: target.pageNumber,
          left: target.left,
          top: target.top,
          width: target.width,
          height: target.height,
        })
      : missingEvidenceAnchor(),
    payload: {
      item,
      level: item.level,
      kind: item.kind,
      text: item.text,
      confidence: item.confidence,
      pageNumber: item.pageNumber,
    },
  };
}

export function layoutLevelLabel(level: LayoutLevel) {
  if (level === "block") return "Block";
  if (level === "paragraph") return "Paragraph";
  if (level === "line") return "Line";
  return "Word";
}

import { buildColorMap, segmentDisplayLabel } from "@/lib/segments";

import { getScrollTarget } from "./layout-blocks-geometry";
import type { LayoutDocument, LayoutItem } from "./layout-blocks-types";
import {
  createSegmentedDocumentModel,
  type DocumentSegment,
  type SegmentAnchor,
  type SegmentedDocumentModel,
} from "./segmented-document-model";

export function createOcrSegmentedDocumentModel({
  document,
  items,
}: {
  document: LayoutDocument;
  items: readonly LayoutItem[];
}): SegmentedDocumentModel {
  const colors = buildColorMap(items.map(layoutItemSegmentLabel));
  const pageByNumber = new Map(
    document.pages.map((page) => [page.pageNumber, page]),
  );
  const segments: DocumentSegment[] = [];
  const anchors: SegmentAnchor[] = [];

  items.forEach((item, index) => {
    const label = layoutItemSegmentLabel(item);
    const segment: DocumentSegment = {
      id: layoutItemSegmentId(item),
      label,
      pages: [],
      color:
        colors.get(label) ??
        colors.get(segmentDisplayLabel(label)) ??
        "var(--color-muted-foreground)",
      confidence: item.confidence ?? null,
      index,
      sourceId: item.id,
    };
    const page = pageByNumber.get(item.pageNumber);
    if (page) {
      const target = getScrollTarget(item, page);
      segment.pages = [target.pageNumber];
      anchors.push({
        id: `${segment.id}:anchor`,
        segmentId: segment.id,
        pageNumber: target.pageNumber,
        bounds: {
          x: target.left / 100,
          y: target.top / 100,
          width: target.width / 100,
          height: target.height / 100,
        },
      });
    }
    segments.push(segment);
  });

  return createSegmentedDocumentModel({
    anchors,
    pages: document.pages.map((page) => ({
      pageNumber: page.pageNumber,
      width: page.width,
      height: page.height,
    })),
    segments,
  });
}

function layoutItemSegmentLabel(item: LayoutItem): string {
  return segmentDisplayLabel(item.text || item.kind || item.level);
}

function layoutItemSegmentId(item: LayoutItem): string {
  return `layout:${item.id}`;
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

import { itemToQuad, toSvgPoints } from "./layout-blocks-geometry";
import type {
  LayoutItem,
  LayoutLevel,
  LayoutPage,
} from "./layout-blocks-types";

const OVERLAY_BLUE = "rgb(37 99 235)";
const OVERLAY_ACTIVE_PURPLE = "rgb(147 51 234)";
const OVERLAY_ACTIVE_PURPLE_FILL = "rgb(147 51 234 / 0.12)";
const OVERLAY_STROKE_WIDTH = 1.6;
const OVERLAY_ACTIVE_STROKE_WIDTH = 2.2;

export function LayoutOverlayLayer({
  activeItemId,
  className,
  interactive = false,
  items,
  onItemClick,
  onItemPointerEnter,
  onItemPointerLeave,
  page,
  rotation = page.rotation,
  selectedItemId,
  visibleLevels,
}: {
  activeItemId?: string | null;
  className?: string;
  interactive?: boolean;
  items: LayoutItem[];
  onItemClick?: (item: LayoutItem) => void;
  onItemPointerEnter?: (item: LayoutItem) => void;
  onItemPointerLeave?: () => void;
  page: LayoutPage;
  rotation?: number;
  selectedItemId?: string | null;
  visibleLevels?: readonly LayoutLevel[];
}) {
  const visibleLevelSet = React.useMemo(
    () => (visibleLevels?.length ? new Set(visibleLevels) : null),
    [visibleLevels],
  );
  const renderedItems = React.useMemo(
    () =>
      visibleLevelSet
        ? items.filter((item) => visibleLevelSet.has(item.level))
        : items,
    [items, visibleLevelSet],
  );

  return (
    <svg
      aria-hidden={!interactive}
      className={cn(
        "absolute inset-0 z-10 size-full",
        interactive ? "pointer-events-auto" : "pointer-events-none",
        className,
      )}
      preserveAspectRatio="none"
      viewBox="0 0 100 100"
    >
      {renderedItems.map((item) => {
        const quad = itemToQuad(item, page);
        if (!quad) return null;

        const isActive = item.id === activeItemId;
        const isSelected = item.id === selectedItemId;
        const isEmphasized = isActive || isSelected;

        return (
          <polygon
            key={item.id}
            data-item-id={item.id}
            points={toSvgPoints(quad, page, rotation)}
            vectorEffect="non-scaling-stroke"
            role={interactive ? "button" : undefined}
            tabIndex={interactive ? 0 : undefined}
            aria-label={
              interactive
                ? `${item.level} ${item.text.trim() || "layout item"}`
                : undefined
            }
            className={cn(
              "transition-[fill,stroke,stroke-width]",
              interactive && "cursor-pointer outline-none",
              interactive && "focus-visible:outline-none",
            )}
            style={{
              fill: isEmphasized ? OVERLAY_ACTIVE_PURPLE_FILL : "transparent",
              stroke: isEmphasized ? OVERLAY_ACTIVE_PURPLE : OVERLAY_BLUE,
            }}
            strokeWidth={
              isEmphasized ? OVERLAY_ACTIVE_STROKE_WIDTH : OVERLAY_STROKE_WIDTH
            }
            onClick={() => onItemClick?.(item)}
            onKeyDown={(event) => {
              if (!interactive) return;
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                onItemClick?.(item);
              }
            }}
            onPointerEnter={() => onItemPointerEnter?.(item)}
            onPointerLeave={onItemPointerLeave}
          />
        );
      })}
    </svg>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

import { InteractiveItemList } from "./interactive-item-list";
import {
  layoutLevelLabel,
  type LayoutEvidenceItem,
} from "./layout-blocks-model";

const ROW_ESTIMATE_SIZE = 84;

export function LayoutBlocksPanel({
  activeItemId,
  className,
  emptyLabel = "No layout items found.",
  items,
  onActiveItemIdChange,
  onNavigateItem,
  onSelectedItemIdChange,
  renderItemContent,
  selectedItemId,
}: {
  activeItemId?: string | null;
  className?: string;
  emptyLabel?: string;
  items: LayoutEvidenceItem[];
  onActiveItemIdChange?: (itemId: string | null) => void;
  onNavigateItem?: (
    item: LayoutEvidenceItem,
    options?: ScrollToOptions,
  ) => void;
  onSelectedItemIdChange?: (itemId: string | null) => void;
  renderItemContent?: (item: LayoutEvidenceItem) => React.ReactNode;
  selectedItemId?: string | null;
}) {
  return (
    <div
      data-slot="layout-blocks-panel"
      className={cn("bg-background flex min-h-0 flex-col", className)}
    >
      <InteractiveItemList
        aria-label="OCR blocks"
        activeItemId={activeItemId}
        emptyLabel={emptyLabel}
        estimateSize={ROW_ESTIMATE_SIZE}
        items={items}
        onActivateItem={(item) => {
          onSelectedItemIdChange?.(item.id);
          onNavigateItem?.(item, { behavior: "smooth" });
        }}
        onClearPreview={() => onActiveItemIdChange?.(null)}
        onClearSelection={() => onSelectedItemIdChange?.(null)}
        onPreviewItem={(item) => {
          onActiveItemIdChange?.(item.id);
          onNavigateItem?.(item, { behavior: "auto" });
        }}
        onVisibleItemChange={(item) => {
          onActiveItemIdChange?.(item.id);
          onNavigateItem?.(item, { behavior: "auto" });
        }}
        renderItem={(item, state) => (
          <LayoutItemRow
            item={item}
            isActive={state.isActive}
            isSelected={state.isSelected}
            renderItemContent={renderItemContent}
          />
        )}
        selectedItemId={selectedItemId}
      />
    </div>
  );
}

function LayoutItemRow({
  isActive,
  isSelected,
  item,
  renderItemContent,
}: {
  isActive: boolean;
  isSelected: boolean;
  item: LayoutEvidenceItem;
  renderItemContent?: (item: LayoutEvidenceItem) => React.ReactNode;
}) {
  const { confidence, pageNumber, text: rawText } = item.payload;
  const confidenceLabel =
    confidence == null ? "Unknown" : `${Math.round(confidence * 100)}%`;
  const text = rawText.replace(/\s+/g, " ").trim();

  return (
    <span
      className={cn(
        "bg-background hover:bg-muted/40 focus-visible:ring-ring block w-full rounded-lg border p-3 text-left transition-[background-color,border-color,box-shadow] outline-none focus-visible:ring-2",
        isActive && "border-primary/50 bg-primary/5",
        isSelected && "border-primary bg-primary/8 shadow-sm",
      )}
    >
      <div className="flex min-w-0 items-center gap-2">
        <span className="bg-muted text-muted-foreground rounded-md px-1.5 py-0.5 text-[11px] font-medium">
          {layoutLevelLabel(item.payload.level)}
        </span>
        <span
          className={cn(
            "text-[11px] font-medium",
            confidence != null && confidence < 0.9
              ? "text-destructive"
              : "text-muted-foreground",
          )}
        >
          {confidenceLabel}
        </span>
        <span className="text-muted-foreground ml-auto text-[11px]">
          p. {pageNumber}
        </span>
      </div>
      <div className="text-foreground mt-2 text-sm leading-5">
        {renderItemContent ? (
          renderItemContent(item)
        ) : (
          <span className="line-clamp-3">{text || "Empty text"}</span>
        )}
      </div>
    </span>
  );
}
